    'Register'=>'Μητρώο',
    'RegisterSimpleRisk'=>'Εγγραφείτε SimpleRisk',
    'RegistrationText'=>'Οι καταχωρημένες παρουσίες SimpleRisk λαμβάνουν αμέσως πρόσβαση στα πρόσθετα στοιχεία αναβάθμισης και ασφαλούς πλαισίου ελέγχου (SCF). Το Upgrade Extra παρέχει τη δυνατότητα δημιουργίας αντιγράφων ασφαλείας και αναβάθμισης της παρουσίας SimpleRisk με το πάτημα ενός κουμπιού. Το Secure Controls Framework (SCF) Extra παρέχει ένα κοινό πλαίσιο ελέγχου που είναι ενσωματωμένο στη λειτουργία SimpleRisk Governance. Κατά την εγγραφή του SimpleRisk, τα στοιχεία εγγραφής σας θα σταλούν σε έναν διακομιστή που φιλοξενείται από το SimpleRisk. Οι πληροφορίες εγγραφής που παρέχονται θα χρησιμοποιηθούν από το SimpleRisk για την ειδοποίηση των πελατών για νέες εκδόσεις και ενημερώσεις ασφαλείας. Η πράξη εγγραφής του SimpleRisk θα σας επιτρέψει να συμμετέχετε στις επικοινωνίες μάρκετινγκ, αλλά μπορείτε να εξαιρεθείτε ανά πάσα στιγμή χρησιμοποιώντας τον σύνδεσμο κατάργησης εγγραφής σε αυτές τις επικοινωνίες. Το SimpleRisk σέβεται το απόρρητο των πελατών μας και οι πληροφορίες που μας παρέχονται μέσω της διαδικασίας εγγραφής στο SimpleRisk δεν θα πωληθούν ποτέ σε τρίτους.',
